const key = crypto.randomBytes(32);
const data = Buffer.from('Sensitive information', 'utf8');

// Encryption process
const cipher = crypto.createCipheriv('aes-256-gcm', key, crypto.randomBytes(16));
const encrypted = Buffer.concat([cipher.update(data), cipher.final()]);
const authTag = cipher.getAuthTag();

// Verification
const decipher = crypto.createDecipheriv('aes-256-gcm', key, cipher.iv);
decipher.setAuthTag(authTag);
const decrypted = Buffer.concat([decipher.update(encrypted), decipher.final()]);

console.assert(decrypted.toString() === 'Sensitive information');

